package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateCltvSlack      = 1
	candidateMaxLabels      = 12
	candidateMaxAttempts    = 96
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
	if fee < lnwire.MilliSatoshi(math.MaxInt64) {
		fee++
	}

	return fee
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityState struct {
	upperFail lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	known     bool
	conf      float64
	failures  uint32
	successes uint32
	blocked   bool
}

var candidateKnowledge = struct {
	sync.Mutex
	states map[candidateEdgeKey]*candidateLiquidityState
}{
	states: make(map[candidateEdgeKey]*candidateLiquidityState),
}

func candidateMutableState(
	key candidateEdgeKey) *candidateLiquidityState {

	state := candidateKnowledge.states[key]
	if state == nil {
		state = &candidateLiquidityState{}
		candidateKnowledge.states[key] = state
	}

	return state
}

func candidateStateSnapshot(
	key candidateEdgeKey) candidateLiquidityState {

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateKnowledge.states[key]
	if state == nil {
		return candidateLiquidityState{}
	}

	return *state
}

func candidateClampState(state *candidateLiquidityState,
	capacity lnwire.MilliSatoshi) {

	if state.lowerOK > capacity {
		state.lowerOK = capacity
	}
	if state.estimate > capacity {
		state.estimate = capacity
	}
	if state.upperFail > capacity {
		state.upperFail = capacity
	}
	if state.upperFail != 0 && state.lowerOK >= state.upperFail {
		state.lowerOK = state.upperFail - 1
	}
	if state.lowerOK < 0 {
		state.lowerOK = 0
	}
	if state.estimate < 0 {
		state.estimate = 0
	}
}

func candidateRecordProbe(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	forward := candidateMutableState(edge.key)
	if amt > forward.lowerOK {
		forward.lowerOK = amt
	}

	highEstimate := edge.capacity * 92 / 100
	if highEstimate < amt {
		highEstimate = amt
	}
	if !forward.known || forward.estimate < highEstimate {
		forward.estimate = highEstimate
	}

	if forward.upperFail != 0 && amt >= forward.upperFail {
		forward.upperFail = 0
	}
	if forward.failures > 0 {
		forward.failures--
	}

	forward.known = true
	forward.conf = math.Max(forward.conf, 0.88)
	forward.successes++
	candidateClampState(forward, edge.capacity)

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	reverseUpper := edge.capacity - amt + 1
	if reverseUpper < 1 {
		reverseUpper = 1
	}
	if reverse.upperFail == 0 || reverseUpper < reverse.upperFail {
		reverse.upperFail = reverseUpper
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.82)
	candidateClampState(reverse, edge.capacity)
}

func candidateRecordFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	forward := candidateMutableState(edge.key)
	if forward.upperFail == 0 || amt < forward.upperFail {
		forward.upperFail = amt
	}

	if forward.lowerOK >= amt {
		forward.lowerOK = 0
	}

	depletedEstimate := amt * 7 / 32
	capEstimate := edge.capacity / 12
	if depletedEstimate > capEstimate {
		depletedEstimate = capEstimate
	}
	if depletedEstimate < forward.lowerOK {
		depletedEstimate = forward.lowerOK
	}
	if !forward.known || forward.estimate > depletedEstimate {
		forward.estimate = depletedEstimate
	}

	forward.known = true
	forward.conf = math.Max(forward.conf, 0.96)
	forward.failures++
	candidateClampState(forward, edge.capacity)

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	reverseLower := edge.capacity - amt + 1
	if reverseLower < 1 {
		reverseLower = 1
	}
	if reverseLower > reverse.lowerOK {
		reverse.lowerOK = reverseLower
	}

	highEstimate := edge.capacity * 92 / 100
	if highEstimate < reverseLower {
		highEstimate = reverseLower
	}
	if !reverse.known || reverse.estimate < highEstimate {
		reverse.estimate = highEstimate
	}
	if reverse.upperFail != 0 &&
		reverse.lowerOK >= reverse.upperFail {

		reverse.upperFail = 0
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.9)
	reverse.successes++
	candidateClampState(reverse, edge.capacity)
}

func candidateRecordSettlement(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	forward := candidateMutableState(edge.key)

	preEstimate := forward.estimate
	if !forward.known {
		preEstimate = edge.capacity * 92 / 100
	}
	if preEstimate < forward.lowerOK {
		preEstimate = forward.lowerOK
	}
	if preEstimate < amt {
		preEstimate = amt
	}

	forward.estimate = preEstimate - amt
	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}
	if forward.upperFail > amt {
		forward.upperFail -= amt
	} else {
		forward.upperFail = 0
	}

	forward.known = true
	forward.conf = math.Max(forward.conf, 0.9)
	forward.successes++
	if forward.failures > 0 {
		forward.failures--
	}
	candidateClampState(forward, edge.capacity)

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	if reverse.known {
		reverse.estimate += amt
	} else {
		reverse.estimate = amt
	}
	reverse.lowerOK += amt
	if reverse.upperFail != 0 {
		reverse.upperFail += amt
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.92)
	reverse.successes++
	candidateClampState(reverse, edge.capacity)
}

func candidateBlockEdge(edge *candidateEdge) {
	if edge == nil {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	state.blocked = true
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionPenalty  map[candidateEdgeKey]float64
	sessionBlocked  map[candidateEdgeKey]bool
	sessionFailedAt map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailures map[candidateEdgeKey]uint32
	attempts        uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	router := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[candidateEdgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		sessionPenalty:  make(map[candidateEdgeKey]float64),
		sessionBlocked:  make(map[candidateEdgeKey]bool),
		sessionFailedAt: make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailures: make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		router.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[key.to] = append(
					router.incomingEdges[key.to], edge,
				)
				router.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func candidatePriorProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.capacity <= 0 || amt <= 0 {
		return 0
	}

	ratio := float64(amt) / float64(edge.capacity)

	lowMode := 0.46 * math.Exp(-ratio/0.022)
	highMode := 0.50 /
		(1 + math.Exp((ratio-0.93)/0.038))

	probability := 0.018 + lowMode + highMode
	if probability > 0.985 {
		return 0.985
	}
	if probability < 0.005 {
		return 0.005
	}

	return probability
}

func candidateClampProbability(probability float64) float64 {
	if probability > 0.995 {
		return 0.995
	}
	if probability < 0.005 {
		return 0.005
	}

	return probability
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	state := candidateStateSnapshot(edge.key)
	if state.blocked {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 1
	}

	if state.upperFail != 0 && amt >= state.upperFail {
		return 0
	}
	if state.lowerOK >= amt {
		return 0.995
	}

	prior := candidatePriorProbability(edge, amt)
	if !state.known {
		return prior
	}

	if state.upperFail != 0 {
		lower := state.lowerOK
		span := state.upperFail - lower
		if span <= 0 {
			return 0.005
		}

		position := float64(amt-lower) / float64(span)
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		bounded := 0.015 +
			0.62*math.Pow(1-position, 2)
		if state.estimate >= amt && bounded < 0.78 {
			bounded = 0.78
		}

		probability := 0.82*bounded + 0.18*prior
		if state.failures > state.successes+1 {
			probability *= 0.82
		}

		return candidateClampProbability(probability)
	}

	if state.estimate >= amt {
		margin := float64(state.estimate-amt+1) /
			float64(edge.capacity+1)
		probability := 0.84 + 0.11*state.conf +
			0.04*math.Min(margin, 1)

		return candidateClampProbability(probability)
	}

	deficit := float64(amt-state.estimate) /
		math.Max(float64(edge.capacity), 1)
	probability := 0.30 * prior *
		math.Exp(-deficit/0.16)
	if state.successes > state.failures {
		probability += 0.08
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	penalty := r.sessionPenalty[edge.key]
	failedAt := r.sessionFailedAt[edge.key]
	if failedAt == 0 || amt >= failedAt {
		return penalty
	}

	ratio := float64(amt) / float64(failedAt)
	scale := 0.04 + ratio*ratio

	return penalty * scale
}

type candidateLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64

	edge   *candidateEdge
	next   *candidateLabel
	active bool
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) < 1e-12 {
		return q[i].amount < q[j].amount
	}

	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func candidateLabelContains(label *candidateLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}

	return false
}

func candidateDominates(a, b *candidateLabel) bool {
	return a.active &&
		a.score <= b.score+1e-12 &&
		a.amount <= b.amount
}

func candidatePruneLabels(labels []*candidateLabel,
	deliver lnwire.MilliSatoshi) {

	active := 0
	for _, label := range labels {
		if label.active {
			active++
		}
	}
	if active <= candidateMaxLabels {
		return
	}

	var worst *candidateLabel
	worstMetric := math.Inf(-1)

	for _, label := range labels {
		if !label.active {
			continue
		}

		amountRatio := math.Max(
			float64(label.amount)/
				math.Max(float64(deliver), 1),
			1,
		)
		metric := label.score + 0.16*math.Log(amountRatio)
		if metric > worstMetric {
			worst = label
			worstMetric = metric
		}
	}

	if worst != nil {
		worst.active = false
	}
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source is payment target")
	}

	labels := make(map[route.Vertex][]*candidateLabel)
	initial := &candidateLabel{
		node:   r.spec.Target,
		amount: deliver,
		active: true,
	}
	labels[r.spec.Target] = []*candidateLabel{initial}

	queue := &candidateQueue{}
	heap.Push(queue, initial)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateLabel)
		if !item.active {
			continue
		}

		if item.node == r.source {
			built, err := r.buildRoute(deliver, item)
			if err != nil {
				return nil, 0, err
			}

			return built, item.risk, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amountOver := item.amount
			if !edge.usable(amountOver) {
				continue
			}

			probability := r.edgeProbability(edge, amountOver)
			if probability <= 0 {
				continue
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOver)
				if sending > lnwire.MilliSatoshi(math.MaxInt64)-fee {
					continue
				}
				sending += fee
			}

			edgeRisk := -math.Log(probability) +
				r.edgePenalty(edge, amountOver)
			feePenalty := 10 * float64(fee) /
				math.Max(float64(deliver), 1)
			newLabel := &candidateLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + edgeRisk +
					feePenalty + 0.01,
				risk:   item.risk + edgeRisk,
				edge:   edge,
				next:   item,
				active: true,
			}

			nodeLabels := labels[newLabel.node]
			dominated := false
			for _, old := range nodeLabels {
				if candidateDominates(old, newLabel) {
					dominated = true
					break
				}
			}
			if dominated {
				continue
			}

			for _, old := range nodeLabels {
				if candidateDominates(newLabel, old) {
					old.active = false
				}
			}

			nodeLabels = append(nodeLabels, newLabel)
			labels[newLabel.node] = nodeLabels
			candidatePruneLabels(nodeLabels, deliver)

			if newLabel.active {
				heap.Push(queue, newLabel)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	sourceLabel *candidateLabel) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	for current := sourceLabel; current != nil &&
		current.edge != nil; current = current.next {

		path = append(path, current.edge)
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("selected route is incomplete")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, fmt.Errorf(
				"broken path at %v", path[i-1].key.to,
			)
		}
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		fee := nextEdge.fee(amounts[i+1])
		if amounts[i+1] >
			lnwire.MilliSatoshi(math.MaxInt64)-fee {

			return nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(nextEdge.timeLockDelta) +
			candidateCltvSlack
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	result := amt / d
	if amt%d != 0 {
		result++
	}

	return result
}

func candidateFraction(amt lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	d := lnwire.MilliSatoshi(denominator)
	n := lnwire.MilliSatoshi(numerator)

	whole := amt / d
	remainder := amt % d
	result := whole*n + remainder*n/d
	if remainder*n%d != 0 {
		result++
	}

	return result
}

func candidateShardAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	seen := make(map[lnwire.MilliSatoshi]bool)
	amounts := make([]lnwire.MilliSatoshi, 0, 40)

	add := func(shard lnwire.MilliSatoshi) {
		if shard < minimum || shard > amt || shard <= 0 ||
			seen[shard] {

			return
		}

		seen[shard] = true
		amounts = append(amounts, shard)
	}

	add(amt)
	add(candidateFraction(amt, 7, 8))
	add(candidateFraction(amt, 3, 4))
	add(candidateFraction(amt, 2, 3))
	add(candidateFraction(amt, 3, 5))
	add(candidateFraction(amt, 1, 2))
	add(candidateFraction(amt, 3, 8))
	add(candidateFraction(amt, 1, 3))
	add(candidateFraction(amt, 1, 4))

	limit := partsLeft
	if limit > 32 {
		limit = 32
	}
	for parts := uint32(2); parts <= limit; parts++ {
		add(candidateCeilDiv(amt, parts))
	}

	add(minimum)

	return amounts
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	shards := candidateShardAmounts(amt, partsLeft)
	minimum := candidateCeilDiv(amt, partsLeft)

	progressWeight := 0.82
	if partsLeft <= 4 {
		progressWeight = 0.9
	}

	var bestRoute *route.Route
	var bestShard lnwire.MilliSatoshi
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		progress := math.Log(
			math.Max(
				float64(shard)/
					math.Max(float64(minimum), 1),
				1,
			),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 8 * float64(fee) /
			math.Max(float64(shard), 1)

		utility := -logRisk +
			progressWeight*progress -
			feePenalty
		if shard == amt {
			utility += 0.025
		}

		if bestRoute == nil ||
			utility > bestUtility+1e-12 ||
			(math.Abs(utility-bestUtility) < 1e-12 &&
				shard > bestShard) {

			bestRoute = rt
			bestShard = shard
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	return bestRoute, nil
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []*candidateEdge {

	edges := make([]*candidateEdge, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edges[i] = r.edges[key]
		from = hop.PubKeyBytes
	}

	return edges
}

func candidateRouteAmount(rt *route.Route,
	channelIndex int) lnwire.MilliSatoshi {

	if channelIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[channelIndex-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) penalizeUnknownRoute(
	edges []*candidateEdge, rt *route.Route) {

	for i, edge := range edges {
		if edge == nil {
			continue
		}

		r.sessionPenalty[edge.key] += 0.9
		r.sessionFailures[edge.key]++

		amount := candidateRouteAmount(rt, i)
		if amount > r.sessionFailedAt[edge.key] {
			r.sessionFailedAt[edge.key] = amount
		}

		if r.sessionFailures[edge.key] >= 3 {
			r.sessionBlocked[edge.key] = true
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil {
		return errors.New("reported route is nil")
	}

	edges := r.routeEdges(rt)

	if result.Failure == nil {
		for i, edge := range edges {
			if edge == nil {
				continue
			}

			amount := candidateRouteAmount(rt, i)
			candidateRecordSettlement(edge, amount)
			delete(r.sessionPenalty, edge.key)
			delete(r.sessionFailedAt, edge.key)
			delete(r.sessionFailures, edge.key)
			delete(r.sessionBlocked, edge.key)
		}

		if len(rt.Hops) != 0 {
			firstChan := rt.Hops[0].ChannelID
			spent := rt.TotalAmount
			if r.localBalances[firstChan] > spent {
				r.localBalances[firstChan] -= spent
			} else {
				r.localBalances[firstChan] = 0
			}
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(edges) {
			prefixEnd = len(edges)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := edges[i]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordProbe(
				edge, candidateRouteAmount(rt, i),
			)
			delete(r.sessionPenalty, edge.key)
			delete(r.sessionFailedAt, edge.key)
			delete(r.sessionFailures, edge.key)
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(edges) {
		edge := edges[failIndex]
		if edge == nil {
			return nil
		}

		amount := candidateRouteAmount(rt, failIndex)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(edge, amount)

			r.sessionPenalty[edge.key] += 0.95
			if amount > r.sessionFailedAt[edge.key] {
				r.sessionFailedAt[edge.key] = amount
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			candidateBlockEdge(edge)
			r.sessionBlocked[edge.key] = true

		default:
			r.sessionPenalty[edge.key] += 1.4
			r.sessionFailures[edge.key]++
			if amount > r.sessionFailedAt[edge.key] {
				r.sessionFailedAt[edge.key] = amount
			}
			if r.sessionFailures[edge.key] >= 2 {
				r.sessionBlocked[edge.key] = true
			}
		}

		return nil
	}

	r.penalizeUnknownRoute(edges, rt)

	return nil
}

